  @if(auth()->user()->esSuperAdmin())<section class="card"><h2 id="printer-form-title">Agregar impresora</h2><form id="printer-form" method="post" action="{{ route('admin.impresoras.store') }}">@csrf <span id="printer-method"></span><div class="printer-fields"><label>Nombre<input name="nombre" required maxlength="80" value="{{ old('nombre') }}" placeholder="Recepción"></label><label>Tipo<select name="tipo" required><option value="termica">Térmica</option><option value="documentos">Documentos</option></select></label><label>Conexión<select name="conexion" required><option value="sistema">Sistema / diálogo del navegador</option><option value="usb">USB con controlador del sistema</option><option value="bluetooth">Bluetooth vinculado al sistema</option><option value="red">Red local IP</option><option value="wifi">Wi-Fi IP</option></select></label><label>Papel<select name="papel_mm" required><option value="80">80 mm</option><option value="58">58 mm</option><option value="210">A4</option></select></label><label class="printer-network">IP privada<input name="direccion_ip" inputmode="decimal" placeholder="192.168.1.100" value="{{ old('direccion_ip') }}"></label><label class="printer-network">Puerto TCP<input name="puerto" type="number" min="1" max="65535" value="{{ old('puerto',9100) }}"></label></div><p id="printer-method-hint" class="printer-hint"></p><div class="printer-form-actions"><button type="button" class="btn btn-secondary" id="printer-reset" hidden>Cancelar edición</button><button class="btn btn-primary">Guardar impresora</button></div></form></section>@endif
