@push('scripts')<script>
(()=>{const form=document.getElementById('printer-form');if(!form)return;const base=form.action, method=document.getElementById('printer-method'),title=document.getElementById('printer-form-title'),reset=document.getElementById('printer-reset'),hint=document.getElementById('printer-method-hint');const update=()=>{const type=form.elements.tipo.value,connection=form.elements.conexion.value,direct=type==='termica'&&['red','wifi'].includes(connection);form.querySelectorAll('.printer-network').forEach(el=>el.hidden=!direct);form.elements.direccion_ip.required=direct;form.elements.puerto.required=direct;hint.textContent=direct?'El servidor enviará comandos ESC/POS a esta IP privada. Verifica que tenga acceso a la impresora.':'La impresión abrirá el diálogo del navegador. Selecciona allí la impresora instalada en este dispositivo.';if(type==='documentos')form.elements.papel_mm.value='210';else if(form.elements.papel_mm.value==='210')form.elements.papel_mm.value='80';};form.elements.tipo.addEventListener('change',update);form.elements.conexion.addEventListener('change',update);document.querySelectorAll('[data-edit-printer]').forEach(button=>button.addEventListener('click',()=>{const item=JSON.parse(button.dataset.editPrinter);for(const key of ['nombre','tipo','conexion','direccion_ip','puerto','papel_mm'])form.elements[key].value=item[key]??'';form.action=base+'/'+item.id;method.innerHTML='<input type="hidden" name="_method" value="PUT">';title.textContent='Editar impresora';reset.hidden=false;update();form.scrollIntoView({behavior:'smooth',block:'center'});}));reset.addEventListener('click',()=>{form.reset();form.action=base;method.replaceChildren();title.textContent='Agregar impresora';reset.hidden=true;update();});update();})();
</script>@endpush
